require_once __DIR__.'/../includes/auth.php';require_role(['super_admin','manager','trainer']);$bid=current_branch_id();
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();if(($_POST['action']??'')==='add'){$trainerId=$_POST['trainer_id']?:null;$memberId=(int)$_POST['member_id'];if(user()['role']==='trainer'){$trainerId=(int)(query_value('SELECT id FROM trainers WHERE user_id=?',[user()['id']])?:0);if(!(int)query_value('SELECT COUNT(*) FROM members WHERE id=? AND branch_id=? AND trainer_id=?',[$memberId,$bid,$trainerId])){http_response_code(403);exit('403 — You can create plans only for assigned members.');}}db()->prepare("INSERT INTO workout_plans(branch_id,member_id,trainer_id,title,goal,start_date,end_date,status,notes) VALUES(?,?,?,?,?,?,?,'active',?)")->execute([$bid,$memberId,$trainerId,trim($_POST['title']),trim($_POST['goal']),$_POST['start_date'],$_POST['end_date'],trim($_POST['notes'])]);$planId=(int)db()->lastInsertId();$exercises=array_filter(array_map('trim',explode("\n",$_POST['exercises']??'')));foreach($exercises as $i=>$ex){db()->prepare('INSERT INTO workout_items(plan_id,day_name,exercise,sets,reps,rest_seconds) VALUES(?,?,?,?,?,?)')->execute([$planId,'Day '.($i+1),$ex,3,'10-12',60]);}audit_log('workout.created','workout_plan',$planId,'Workout plan created');flash('success','Workout plan created.');redirect('app/workouts.php');}}
$trainerFilter='';$params=[$bid];if(user()['role']==='trainer'){$tid=(int)(query_value('SELECT id FROM trainers WHERE user_id=?',[user()['id']])?:0);$trainerFilter=' AND w.trainer_id=?';$params[]=$tid;}
$rows=query_all("SELECT w.*,CONCAT(m.first_name,' ',m.last_name) member_name,m.member_code,t.name trainer_name,(SELECT COUNT(*) FROM workout_items wi WHERE wi.plan_id=w.id) items FROM workout_plans w JOIN members m ON m.id=w.member_id LEFT JOIN trainers t ON t.id=w.trainer_id WHERE w.branch_id=? $trainerFilter ORDER BY w.created_at DESC",$params);if(user()['role']==='trainer'){$members=query_all("SELECT id,member_code,CONCAT(first_name,' ',last_name) name FROM members WHERE branch_id=? AND trainer_id=? AND status='active' ORDER BY first_name",[$bid,$tid]);$trainers=query_all("SELECT id,name FROM trainers WHERE id=?",[$tid]);}else{$members=query_all("SELECT id,member_code,CONCAT(first_name,' ',last_name) name FROM members WHERE branch_id=? AND status='active' ORDER BY first_name",[$bid]);$trainers=query_all("SELECT id,name FROM trainers WHERE branch_id=? AND status='active' ORDER BY name",[$bid]);}
$pageTitle='Workout Plans';include __DIR__.'/../includes/header.php'; ?>
<div class="page-actions"><button class="btn btn-primary" data-bs-toggle="modal" data-bs-target="#workoutModal"><i class="fa-solid fa-plus me-2"></i>Create workout plan</button></div><div class="grid-3"><?php foreach($rows as $w): ?><div class="panel"><div class="d-flex justify-content-between"><span class="badge-soft badge-<?= status_badge($w['status']) ?>"><?= e(ucfirst($w['status'])) ?></span><small class="text-muted"><?= (int)$w['items'] ?> exercises</small></div><h3 class="mt-3 mb-1" style="font-family:Manrope;font-size:1.05rem"><?= e($w['title']) ?></h3><p class="text-muted small mb-3"><?= e($w['goal']) ?></p><div class="mini-row"><div class="mini-avatar"><?= e(initials($w['member_name'])) ?></div><div class="grow"><strong><?= e($w['member_name']) ?></strong><small><?= e($w['member_code']) ?></small></div></div><div class="d-flex justify-content-between mt-3 small"><span class="text-muted">Coach</span><span><?= e($w['trainer_name']??'Unassigned') ?></span></div><div class="d-flex justify-content-between mt-2 small"><span class="text-muted">Period</span><span><?= format_date($w['start_date'],'d M') ?> → <?= format_date($w['end_date'],'d M') ?></span></div><p class="text-muted small mt-3 mb-0"><?= e($w['notes']) ?></p></div><?php endforeach; ?></div>
<div class="modal fade" id="workoutModal"><div class="modal-dialog modal-lg modal-dialog-centered"><div class="modal-content"><form method="post"><input type="hidden" name="csrf" value="<?= csrf_token() ?>"><input type="hidden" name="action" value="add"><div class="modal-header"><div><h5>Create workout plan</h5><small class="text-muted">Assign a structured program to a member</small></div><button class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body"><div class="row g-3"><div class="col-md-6"><label class="form-label">Member</label><select name="member_id" class="form-select"><?php foreach($members as $m): ?><option value="<?= $m['id'] ?>"><?= e($m['member_code'].' — '.$m['name']) ?></option><?php endforeach; ?></select></div><div class="col-md-6"><label class="form-label">Trainer</label><select name="trainer_id" class="form-select" <?= user()['role']==='trainer'?'disabled':'' ?>><?php foreach($trainers as $t): ?><option value="<?= $t['id'] ?>"><?= e($t['name']) ?></option><?php endforeach; ?></select></div><div class="col-md-6"><label class="form-label">Plan title</label><input name="title" class="form-control" placeholder="8 Week Strength Base" required></div><div class="col-md-6"><label class="form-label">Goal</label><input name="goal" class="form-control" placeholder="Strength / Fat loss / Mobility"></div><div class="col-md-6"><label class="form-label">Start date</label><input type="date" name="start_date" value="<?= date('Y-m-d') ?>" class="form-control"></div><div class="col-md-6"><label class="form-label">End date</label><input type="date" name="end_date" value="<?= date('Y-m-d',strtotime('+6 weeks')) ?>" class="form-control"></div><div class="col-12"><label class="form-label">Exercises — one per line</label><textarea name="exercises" class="form-control" rows="5" placeholder="Barbell Squat&#10;Bench Press&#10;Lat Pulldown&#10;Romanian Deadlift"></textarea><small class="text-muted">Quick-entry mode creates a 3 × 10–12 default prescription for each item; extend it later as needed.</small></div><div class="col-12"><label class="form-label">Coach notes</label><textarea name="notes" class="form-control" rows="2"></textarea></div></div></div><div class="modal-footer"><button class="btn btn-primary">Create plan</button></div></form></div></div></div>
